-- generated by tools/gencatalog, do not edit by hand

CREATE TABLE absences (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    employee_id BIGINT REFERENCES employees(id) NOT NULL,
    kind TEXT CHECK (kind IN ('VACATION', 'SICK_LEAVE', 'OTHER')) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT chk_absences_period CHECK (end_date >= start_date)
);

CREATE TABLE absence_revisions (
    id              BIGINT       PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    absence_id BIGINT       NOT NULL REFERENCES absences(id) ON DELETE CASCADE,
    revision_number INTEGER      NOT NULL CHECK (revision_number >= 1),
    change          JSONB        NOT NULL,
    changed_by      UUID         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_absence_revisions_revision
        UNIQUE (absence_id, revision_number)
);

CREATE INDEX idx_absences_employee_id
    ON absences (employee_id);

CREATE INDEX idx_absences_active
    ON absences (id)
    WHERE is_deleted = FALSE;

CREATE INDEX idx_absence_revisions_absence_id
    ON absence_revisions (absence_id);

CREATE INDEX idx_absence_revisions_covering_agg
    ON absence_revisions (absence_id, revision_number DESC)
    INCLUDE (changed_at, changed_by, change);

CREATE INDEX idx_absence_revisions_changed_at
    ON absence_revisions (changed_at);

CREATE INDEX idx_absences_employee_period ON absences (employee_id, start_date, end_date) WHERE is_deleted = FALSE;

CREATE OR REPLACE VIEW v_expanded_absence AS
SELECT
    t.id,
    t.employee_id,
    t.kind,
    t.start_date,
    t.end_date,
    t.is_deleted,
    agg.revision,
    agg.last_changer,
    agg.created_at,
    agg.updated_at,
    agg.deleted_at
FROM absences t
LEFT JOIN (
    SELECT
        absence_id,
        MAX(revision_number) AS revision,
        MAX(changed_at) AS updated_at,
        (ARRAY_AGG(changed_by ORDER BY revision_number DESC))[1] AS last_changer,
        MIN(changed_at) FILTER (WHERE revision_number = 1) AS created_at,
        MAX(changed_at) FILTER (
            WHERE change @> '[{"path": "/is_deleted", "value": true}]'::jsonb
        ) AS deleted_at
    FROM absence_revisions
    GROUP BY absence_id
) agg ON agg.absence_id = t.id;

COMMENT ON TABLE absences IS
    'Absences of employees: vacations, sick leaves and other periods. Readable by the HR roles only. Stores the current state of each record.';

COMMENT ON TABLE absence_revisions IS
    'Immutable audit log of changes applied to absences. Read-only from the application perspective.';

COMMENT ON VIEW v_expanded_absence IS
    'Read-only view that enriches each absence with its latest revision number, '
    'last changer UUID, and lifecycle timestamps derived from the revision log.';
